// The TSL is generated by the original browser converter, NEVER by another
// algorithm. Only GPU H.264/AAC packaging is delegated to local PC FFmpeg.
const ROOT='/api/mp4/jobs';
const aborted=()=>new DOMException('変換を中止しました','AbortError');
const check=signal=>{if(signal?.aborted)throw aborted();};
async function json(url,options={}){
 const res=await fetch(url,options);
 let data;try{data=await res.json();}catch{data={};}
 if(!res.ok)throw Error(data.error||'PC native MP4 request failed');
 return data;
}
function nap(ms,signal){
 return new Promise((resolve,reject)=>{
  check(signal);
  const done=()=>{clearTimeout(timer);signal?.removeEventListener('abort',cancel);resolve();};
  const cancel=()=>{clearTimeout(timer);signal?.removeEventListener('abort',cancel);reject(aborted());};
  const timer=setTimeout(done,ms);
  signal?.addEventListener('abort',cancel,{once:true});
 });
}
export async function exportFaithfulNativeMp4({
 file,tslBlob,plan,source,signal,onProgress=()=>{}
}={}){
 check(signal);
 const health=await json('/health',{signal,cache:'no-store'});
 if(!health.nativeMp4||!health.ffmpeg||!health.ffprobe)
  throw Error('PCネイティブMP4環境が見つかりません');
 const metadata={
  width:plan.width,height:plan.height,
  count:plan.count,ticks:plan.totalTicks,
  native16:plan.native16,fps:plan.fps,
  sourceWidth:source.width,sourceHeight:source.height
 };
 onProgress({state:'uploading',message:'元動画をPC側へ転送中'});
 const job=await json(ROOT,{method:'POST',body:file,signal,
  headers:{'Content-Type':'application/octet-stream',
   'X-TASL-Plan':btoa(JSON.stringify(metadata))}
 });
 const url=ROOT+'/'+encodeURIComponent(job.id);
 const onAbort=()=>{fetch(url+'/cancel',{method:'POST',keepalive:true}).catch(()=>{});};
 signal?.addEventListener('abort',onAbort,{once:true});
 try{
  check(signal);
  onProgress({state:'uploading',message:'正規アルゴリズムで作成したTSLを転送中'});
  await json(url+'/tsl',{method:'POST',signal,body:tslBlob,
   headers:{'Content-Type':'application/octet-stream'}});
  check(signal);
  await json(url+'/start',{method:'POST',signal});
  while(true){
   check(signal);
   const state=await json(url+'/status',{signal,cache:'no-store'});
   onProgress(state);
   if(state.state==='error')throw Error(state.message||'PC版MP4変換に失敗しました');
   if(state.state==='cancelled')throw aborted();
   if(state.state==='done'&&state.reportReady!==false){
    return {url:url+'/result',reportUrl:url+'/report',encoder:state.encoder||'',
     size:state.size||0,width:state.width,height:state.height,total:state.total};
   }
   await nap(550,signal);
  }
 }finally{signal?.removeEventListener('abort',onAbort);}
}